WITH lines AS (SELECT id, effective_from, EXPLODE_OUTER(tier_prices) AS element FROM price_tiers), filtered AS (SELECT *, DATE_ADD(effective_from, 14) AS effective_from_plus_14d, COALESCE(element, 0) AS element_filled FROM lines WHERE effective_from > DATE '2024-05-05'), metrics AS (SELECT effective_from_plus_14d, element_filled, PERCENT_RANK() OVER (ORDER BY element NULLS LAST) AS element_percent_rank, PERCENT_RANK() OVER (ORDER BY element_filled DESC NULLS LAST) AS element_filled_percent_rank, RANK() OVER (ORDER BY element) AS element_rank FROM filtered), metrics_price_tiers AS (SELECT element_percent_rank, element_filled_percent_rank, RANK() OVER w_recent AS element_percent_rank_rank FROM metrics WHERE element_rank > 5 WINDOW w_recent AS (ORDER BY element_percent_rank DESC NULLS LAST)), valid AS (SELECT *, ROUND(element_filled_percent_rank, 1) AS element_filled_percent_rank_rounded FROM metrics_price_tiers WHERE element_percent_rank_rank >= 6), scored AS (SELECT element_percent_rank, element_filled_percent_rank, CUME_DIST() OVER (ORDER BY element_percent_rank_rank NULLS LAST) AS element_percent_rank_rank_cume_dist, DENSE_RANK() OVER (ORDER BY element_percent_rank_rank) AS element_percent_rank_rank_dense_rank, CUME_DIST() OVER (ORDER BY element_filled_percent_rank_rounded DESC) AS element_filled_percent_rank_rounded_cume_dist, PERCENT_RANK() OVER (ORDER BY element_percent_rank_rank DESC) AS element_percent_rank_rank_percent_rank, DENSE_RANK() OVER (ORDER BY element_filled_percent_rank_rounded DESC NULLS FIRST) AS element_filled_percent_rank_rounded_dense_rank FROM valid) SELECT element_percent_rank, element_filled_percent_rank, element_percent_rank_rank_cume_dist, element_filled_percent_rank_rounded_cume_dist, element_percent_rank_rank_percent_rank, element_filled_percent_rank_rounded_dense_rank FROM scored ORDER BY element_filled_percent_rank_rounded_cume_dist NULLS LAST, element_percent_rank_rank_percent_rank;
